	rows, err := q.db.Query(ctx, listWorkspaceWorkingAgents,
		arg.WorkspaceID,
		arg.WorkType,
		arg.MineRelation,
		arg.MemberID,
		arg.ParentIssueID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkspaceWorkingAgentsRow{}
	for rows.Next() {
		var i ListWorkspaceWorkingAgentsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.AvatarUrl,
			&i.RunningTaskCount,
			&i.IssueIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
