const memberHelperProvisionable = `-- name: MemberHelperProvisionable :one
SELECT
    EXISTS (
        SELECT 1 FROM member m
        WHERE m.workspace_id = $1 AND m.user_id = $2
    ) AS is_member,
    NOT EXISTS (
        SELECT 1 FROM agent a
        WHERE a.workspace_id = $1
          AND a.owner_id = $2
          AND a.kind = 'user'
          AND (a.archived_at IS NULL OR a.system_key = $3)
    ) AS slot_free,
    EXISTS (
        SELECT 1 FROM agent_runtime rt
        WHERE rt.workspace_id = $1
          AND rt.status = 'online'
          AND rt.owner_id = $2
          AND (
              NOT $4::boolean
              OR lower(rt.provider) = ANY($5::text[])
          )
    ) AS has_usable_runtime
`

