const roleAgentProvisionable = `-- name: RoleAgentProvisionable :one
SELECT
    w.template_key,
    NOT EXISTS (
        SELECT 1 FROM agent a
        WHERE a.workspace_id = w.id
          AND a.system_key = 'goosar_role_' || w.template_key
    ) AS slot_free,
    EXISTS (
        SELECT 1 FROM agent_runtime rt
        WHERE rt.workspace_id = w.id
          AND rt.status = 'online'
          AND rt.visibility = 'public'
          AND (
              NOT $1::boolean
              OR lower(rt.provider) = ANY($2::text[])
          )
    ) AS has_public_runtime
FROM workspace w
WHERE w.id = $3 AND w.template_key IS NOT NULL
`

type RoleAgentProvisionableParams struct {
	RestrictProviders bool        `json:"restrict_providers"`
	AllowedProviders  []string    `json:"allowed_providers"`
	WorkspaceID       pgtype.UUID `json:"workspace_id"`
}

type RoleAgentProvisionableRow struct {
	TemplateKey      pgtype.Text `json:"template_key"`
	SlotFree         bool        `json:"slot_free"`
	HasPublicRuntime bool        `json:"has_public_runtime"`
}

func (q *Queries) RoleAgentProvisionable(ctx context.Context, arg RoleAgentProvisionableParams) (RoleAgentProvisionableRow, error) {
	row := q.db.QueryRow(ctx, roleAgentProvisionable, arg.RestrictProviders, arg.AllowedProviders, arg.WorkspaceID)
	var i RoleAgentProvisionableRow
	err := row.Scan(&i.TemplateKey, &i.SlotFree, &i.HasPublicRuntime)
	return i, err
}

